using System;using System.IO;using System.Text;using System.Reflection;using System.Collections;using UnityEngine;using UnityEngine.InputSystem;using LWS.TruckBowling;using LWS.TruckMusicalParking;
namespace LWS.TruckSports {public sealed class SportsFocusProbe:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 [RuntimeInitializeOnLoadMethod]static void Boot(){bool run=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsFocus")>=0;bool before=false;
#if UNITY_EDITOR
 run|=UnityEditor.SessionState.GetBool("LWS.FocusProbe",false);before=UnityEditor.SessionState.GetBool("LWS.FocusBefore",false);UnityEditor.SessionState.SetBool("LWS.FocusProbe",false);
#endif
 if(run){var g=new GameObject("Owned focus-policy reproduction");DontDestroyOnLoad(g);if(!SportsProbeInputIsolation.Active)g.AddComponent<SportsProbeInputIsolation>();g.AddComponent<SportsFocusProbe>().before=before;}}
 bool before,had,restored;ParkingMatch m;Keyboard keyboard;string key,saved,folder;int errors;InputSettings.BackgroundBehavior background;readonly StringBuilder log=new StringBuilder();
 void Check(bool ok,string label){log.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;File.WriteAllText(folder+"/progress.txt",log.ToString());}void Error(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;log.AppendLine("ERROR "+s);}}
 // Deliberately invokes the installed Input System's real focus-disable/sync path.
 // This is a software lifecycle injection, not a claim of physical unplug or OS/hardware focus testing.
 public static void InjectFocus(bool focus){var manager=typeof(InputSystem).GetField("s_Manager",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);manager.GetType().GetMethod("OnFocusChanged",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(manager,new object[]{focus});}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder(before?"FocusBefore":"FocusAfter");background=InputSystem.settings.backgroundBehavior;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;keyboard=InputSystem.AddDevice<Keyboard>();InputSystem.EnableDevice(keyboard);Application.logMessageReceived+=Error;yield return SportsProbeScene.Ensure<ParkingMatch>("TruckMusicalParking");m=FindAnyObjectByType<ParkingMatch>();yield return null;key=m.PreferenceKey;had=SportsPrefs.HasKey(key);saved=SportsPrefs.GetString(key);m.AllBots();m.setup.players[0].source=BowlingSource.Keyboard;Check(m.StartMatch(),"real keyboard assigned and match starts");yield return new WaitForSeconds(.15f);InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.ResetAndDisableAllDevices;InjectFocus(false);yield return null;yield return null;log.AppendLine("MEASURE keyboardAdded="+keyboard.added+" enabled="+keyboard.enabled+" ready="+m.Ready(0)+" paused="+m.Paused+" screen="+m.menus.Screen);
 if(before)Check(keyboard.added&&!keyboard.enabled&&m.Paused&&m.menus.Screen==SportsEventScreen.Join,"REPRODUCED attached working keyboard temporarily disabled by focus misreported as disconnected");else Check(keyboard.added&&!keyboard.enabled&&m.Paused&&m.menus.Screen==SportsEventScreen.Pause,"focus suspension produces ordinary pause, never false reconnect");InjectFocus(true);InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;yield return null;Check(keyboard.added&&keyboard.enabled&&m.Ready(0),"focus synchronization restores same physical-source identity");Restore();log.AppendLine("ERRORS="+errors+". Installed InputSystem focus lifecycle injected with software keyboard; no real hardware/OS focus claim.");File.WriteAllText(folder+"/result.txt",log.ToString());if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Error;InjectFocus(true);if(m!=null)m.SetupScreen();if(key!=null){if(had)SportsPrefs.SetString(key,saved);else SportsPrefs.DeleteKey(key);SportsPrefs.Save();}InputSystem.settings.backgroundBehavior=background;if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);Time.timeScale=1;}void OnDestroy(){Restore();}
#endif
